<?php namespace App\Filament\Resources\UpbringingSurveyResource\RelationManagers;use Filament\Forms;use Filament\Resources\Form;use Filament\Resources\RelationManagers\RelationManager;use Filament\Resources\Table;use Filament\Tables;class QuestionsRelationManager extends RelationManager{protected static string $relationship='questions';protected static ?string $title='Вопросы';public static function form(Form $f):Form{return $f->schema([Forms\Components\Textarea::make('question')->label('Вопрос')->required(),Forms\Components\Select::make('type')->label('Тип')->options(['single'=>'Один вариант','multiple'=>'Несколько вариантов','scale'=>'Шкала','text'=>'Текст'])->required(),Forms\Components\Textarea::make('options_text')->label('Варианты ответов')->helperText('По одному варианту на строку')->dehydrated(false),Forms\Components\TextInput::make('sort_order')->label('Порядок')->numeric()->default(0)]);}public static function table(Table $t):Table{return $t->columns([Tables\Columns\TextColumn::make('sort_order')->label('#')->sortable(),Tables\Columns\TextColumn::make('question')->label('Вопрос')->limit(100),Tables\Columns\BadgeColumn::make('type')->label('Тип')])->headerActions([Tables\Actions\CreateAction::make()->label('Добавить вопрос')->mutateFormDataUsing(function(array $d){if(isset($d['options_text'])){$d['options']=json_encode(array_values(array_filter(array_map('trim',preg_split('/[\r\n]+/',$d['options_text'])))),JSON_UNESCAPED_UNICODE);unset($d['options_text']);}return $d;})])->actions([Tables\Actions\DeleteAction::make()]);}}